import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`regex-memo.content.zh`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<h3>普通字符</h3><table><thead><tr><th style="text-align:left;">表达式</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.</code> 或 <code>[^\\n\\r]</code></td><td style="text-align:left;">除换行符或回车符之外的任意字符</td></tr><tr><td style="text-align:left;"><code>[A-Za-z]</code></td><td style="text-align:left;">字母</td></tr><tr><td style="text-align:left;"><code>[a-z]</code></td><td style="text-align:left;">小写字母</td></tr><tr><td style="text-align:left;"><code>[A-Z]</code></td><td style="text-align:left;">大写字母</td></tr><tr><td style="text-align:left;"><code>\\d</code> 或 <code>[0-9]</code></td><td style="text-align:left;">数字</td></tr><tr><td style="text-align:left;"><code>\\D</code> 或 <code>[^0-9]</code></td><td style="text-align:left;">非数字</td></tr><tr><td style="text-align:left;"><code>_</code></td><td style="text-align:left;">下划线</td></tr><tr><td style="text-align:left;"><code>\\w</code> 或 <code>[A-Za-z0-9_]</code></td><td style="text-align:left;">字母、数字或下划线</td></tr><tr><td style="text-align:left;"><code>\\W</code> 或 <code>[^A-Za-z0-9_]</code></td><td style="text-align:left;"><code>\\w</code> 的反义</td></tr><tr><td style="text-align:left;"><code>\\S</code></td><td style="text-align:left;"><code>\\s</code> 的反义</td></tr></tbody></table><h3>空白字符</h3><table><thead><tr><th style="text-align:left;">表达式</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code></code></td><td style="text-align:left;">空格</td></tr><tr><td style="text-align:left;"><code>\\t</code></td><td style="text-align:left;">制表符</td></tr><tr><td style="text-align:left;"><code>\\n</code></td><td style="text-align:left;">换行符</td></tr><tr><td style="text-align:left;"><code>\\r</code></td><td style="text-align:left;">回车符</td></tr><tr><td style="text-align:left;"><code>\\s</code></td><td style="text-align:left;">空格、制表符、换行符或回车符</td></tr></tbody></table><h3>字符集</h3><table><thead><tr><th style="text-align:left;">表达式</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>[xyz]</code></td><td style="text-align:left;"><code>x</code>、<code>y</code> 或 <code>z</code> 中的一个</td></tr><tr><td style="text-align:left;"><code>[^xyz]</code></td><td style="text-align:left;">非 <code>x</code>、<code>y</code> 和 <code>z</code></td></tr><tr><td style="text-align:left;"><code>[1-3]</code></td><td style="text-align:left;"><code>1</code>、<code>2</code> 或 <code>3</code> 中的一个</td></tr><tr><td style="text-align:left;"><code>[^1-3]</code></td><td style="text-align:left;">非 <code>1</code>、<code>2</code> 和 <code>3</code></td></tr></tbody></table><ul><li>可将字符集视为对方括号内包含的单个字符进行 <code>OR</code> 运算。</li><li>在开方括号 <code>[</code> 之后使用 <code>^</code> 来&quot;取反&quot;字符集。</li><li>在字符集内部，<code>.</code> 表示字面意义上的句点。</li></ul><h3>需要转义的字符</h3><h4>字符集外部</h4><table><thead><tr><th style="text-align:left;">表达式</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>\\.</code></td><td style="text-align:left;">句点</td></tr><tr><td style="text-align:left;"><code>\\^</code></td><td style="text-align:left;">脱字符</td></tr><tr><td style="text-align:left;"><code>\\$</code></td><td style="text-align:left;">美元符号</td></tr><tr><td style="text-align:left;"><code>|</code></td><td style="text-align:left;">管道符</td></tr><tr><td style="text-align:left;"><code>\\\\</code></td><td style="text-align:left;">反斜杠</td></tr><tr><td style="text-align:left;"><code>\\/</code></td><td style="text-align:left;">正斜杠</td></tr><tr><td style="text-align:left;"><code>\\(</code></td><td style="text-align:left;">左括号</td></tr><tr><td style="text-align:left;"><code>\\)</code></td><td style="text-align:left;">右括号</td></tr><tr><td style="text-align:left;"><code>\\[</code></td><td style="text-align:left;">左方括号</td></tr><tr><td style="text-align:left;"><code>\\]</code></td><td style="text-align:left;">右方括号</td></tr><tr><td style="text-align:left;"><code>\\{</code></td><td style="text-align:left;">左花括号</td></tr><tr><td style="text-align:left;"><code>\\}</code></td><td style="text-align:left;">右花括号</td></tr></tbody></table><h4>字符集内部</h4><table><thead><tr><th style="text-align:left;">表达式</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>\\\\</code></td><td style="text-align:left;">反斜杠</td></tr><tr><td style="text-align:left;"><code>\\]</code></td><td style="text-align:left;">右方括号</td></tr></tbody></table><ul><li><code>^</code> 只有紧跟在字符集的开方括号 <code>[</code> 之后时才需要转义。</li><li><code>-</code> 只有出现在两个字母或两个数字之间时才需要转义。</li></ul><h3>量词</h3><table><thead><tr><th style="text-align:left;">表达式</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>{2}</code></td><td style="text-align:left;">恰好 2 个</td></tr><tr><td style="text-align:left;"><code>{2,}</code></td><td style="text-align:left;">至少 2 个</td></tr><tr><td style="text-align:left;"><code>{2,7}</code></td><td style="text-align:left;">至少 2 个但不超过 7 个</td></tr><tr><td style="text-align:left;"><code>*</code></td><td style="text-align:left;">0 个或多个</td></tr><tr><td style="text-align:left;"><code>+</code></td><td style="text-align:left;">1 个或多个</td></tr><tr><td style="text-align:left;"><code>?</code></td><td style="text-align:left;">恰好 0 个或 1 个</td></tr></tbody></table><ul><li>量词放在被限定的表达式<em>之后</em>。</li></ul><h3>边界</h3><table><thead><tr><th style="text-align:left;">表达式</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>^</code></td><td style="text-align:left;">字符串开头</td></tr><tr><td style="text-align:left;"><code>$</code></td><td style="text-align:left;">字符串结尾</td></tr><tr><td style="text-align:left;"><code>\\b</code></td><td style="text-align:left;">单词边界</td></tr></tbody></table><ul><li>单词边界匹配的工作原理： <ul><li>在字符串开头，如果第一个字符是 <code>\\w</code>。</li><li>在字符串内部的两个相邻字符之间，如果第一个字符是 <code>\\w</code> 而第二个字符是 <code>\\W</code>。</li><li>在字符串结尾，如果最后一个字符是 <code>\\w</code>。</li></ul></li></ul><h3>匹配</h3><table><thead><tr><th style="text-align:left;">表达式</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>foo|bar</code></td><td style="text-align:left;">匹配 <code>foo</code> 或 <code>bar</code></td></tr><tr><td style="text-align:left;"><code>foo(?=bar)</code></td><td style="text-align:left;">匹配 <code>foo</code>，前提是其后紧跟着 <code>bar</code></td></tr><tr><td style="text-align:left;"><code>foo(?!bar)</code></td><td style="text-align:left;">匹配 <code>foo</code>，前提是其后<em>不</em>跟着 <code>bar</code></td></tr><tr><td style="text-align:left;"><code>(?&lt;=bar)foo</code></td><td style="text-align:left;">匹配 <code>foo</code>，前提是它跟在 <code>bar</code> 之后</td></tr><tr><td style="text-align:left;"><code>(?&lt;!bar)foo</code></td><td style="text-align:left;">匹配 <code>foo</code>，前提是它<em>不</em>跟在 <code>bar</code> 之后</td></tr></tbody></table><h3>分组与捕获</h3><table><thead><tr><th style="text-align:left;">表达式</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>(foo)</code></td><td style="text-align:left;">捕获组；匹配并捕获 <code>foo</code></td></tr><tr><td style="text-align:left;"><code>(?:foo)</code></td><td style="text-align:left;">非捕获组；匹配 <code>foo</code> 但<em>不</em>捕获 <code>foo</code></td></tr><tr><td style="text-align:left;"><code>(foo)bar\\1</code></td><td style="text-align:left;"><code>\\1</code> 是对第 1 个捕获组的反向引用；匹配 <code>foobarfoo</code></td></tr></tbody></table><ul><li>捕获组仅在以下方法中有意义： <ul><li><code>string.match(regexp)</code></li><li><code>string.matchAll(regexp)</code></li><li><code>string.replace(regexp, callback)</code></li></ul></li><li><code>\\N</code> 是对第 <code>N</code> 个捕获组的反向引用。捕获组从 1 开始编号。</li></ul><h2>参考资料与工具</h2><ul><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Regular_Expressions">MDN</a></li><li><a href="https://leaverou.github.io/regexplained/">RegExplained</a></li></ul>`,26)]]))}};export{a as default};